#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [StandardVolumeFlow; 9] = [
        StandardVolumeFlow::const_new(1234.5, StandardVolumeFlowUnit::StandardCubicMeterPerSecond),
        StandardVolumeFlow::const_new(1234.5, StandardVolumeFlowUnit::StandardCubicMeterPerMinute),
        StandardVolumeFlow::const_new(1234.5, StandardVolumeFlowUnit::StandardCubicMeterPerHour),
        StandardVolumeFlow::const_new(1234.5, StandardVolumeFlowUnit::StandardCubicMeterPerDay),
        StandardVolumeFlow::const_new(
            1234.5,
            StandardVolumeFlowUnit::StandardCubicCentimeterPerMinute,
        ),
        StandardVolumeFlow::const_new(1234.5, StandardVolumeFlowUnit::StandardLiterPerMinute),
        StandardVolumeFlow::const_new(1234.5, StandardVolumeFlowUnit::StandardCubicFootPerSecond),
        StandardVolumeFlow::const_new(1234.5, StandardVolumeFlowUnit::StandardCubicFootPerMinute),
        StandardVolumeFlow::const_new(1234.5, StandardVolumeFlowUnit::StandardCubicFootPerHour),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(StandardVolumeFlowUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            StandardVolumeFlow::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in StandardVolumeFlowUnit::ALL {
            assert_eq!(
                StandardVolumeFlow::const_new(v, unit).as_base().to_bits(),
                StandardVolumeFlow::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = StandardVolumeFlow::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            StandardVolumeFlow::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in StandardVolumeFlowUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        StandardVolumeFlow::from_base(0.0).auto_unit().unit,
        StandardVolumeFlowUnit::StandardCubicMeterPerSecond
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Sm³/s".parse::<StandardVolumeFlowUnit>(),
        Ok(StandardVolumeFlowUnit::StandardCubicMeterPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "Sm³/s").parse::<StandardVolumeFlow>(),
        Ok(StandardVolumeFlow::new(
            2.5,
            StandardVolumeFlowUnit::StandardCubicMeterPerSecond
        ))
    );
    assert_eq!(
        "Sm³/min".parse::<StandardVolumeFlowUnit>(),
        Ok(StandardVolumeFlowUnit::StandardCubicMeterPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "Sm³/min").parse::<StandardVolumeFlow>(),
        Ok(StandardVolumeFlow::new(
            2.5,
            StandardVolumeFlowUnit::StandardCubicMeterPerMinute
        ))
    );
    assert_eq!(
        "Sm³/h".parse::<StandardVolumeFlowUnit>(),
        Ok(StandardVolumeFlowUnit::StandardCubicMeterPerHour)
    );
    assert_eq!(
        format!("2.5 {}", "Sm³/h").parse::<StandardVolumeFlow>(),
        Ok(StandardVolumeFlow::new(
            2.5,
            StandardVolumeFlowUnit::StandardCubicMeterPerHour
        ))
    );
    assert_eq!(
        "Sm³/d".parse::<StandardVolumeFlowUnit>(),
        Ok(StandardVolumeFlowUnit::StandardCubicMeterPerDay)
    );
    assert_eq!(
        format!("2.5 {}", "Sm³/d").parse::<StandardVolumeFlow>(),
        Ok(StandardVolumeFlow::new(
            2.5,
            StandardVolumeFlowUnit::StandardCubicMeterPerDay
        ))
    );
    assert_eq!(
        "sccm".parse::<StandardVolumeFlowUnit>(),
        Ok(StandardVolumeFlowUnit::StandardCubicCentimeterPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "sccm").parse::<StandardVolumeFlow>(),
        Ok(StandardVolumeFlow::new(
            2.5,
            StandardVolumeFlowUnit::StandardCubicCentimeterPerMinute
        ))
    );
    assert_eq!(
        "slm".parse::<StandardVolumeFlowUnit>(),
        Ok(StandardVolumeFlowUnit::StandardLiterPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "slm").parse::<StandardVolumeFlow>(),
        Ok(StandardVolumeFlow::new(
            2.5,
            StandardVolumeFlowUnit::StandardLiterPerMinute
        ))
    );
    assert_eq!(
        "Sft³/s".parse::<StandardVolumeFlowUnit>(),
        Ok(StandardVolumeFlowUnit::StandardCubicFootPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "Sft³/s").parse::<StandardVolumeFlow>(),
        Ok(StandardVolumeFlow::new(
            2.5,
            StandardVolumeFlowUnit::StandardCubicFootPerSecond
        ))
    );
    assert_eq!(
        "scfm".parse::<StandardVolumeFlowUnit>(),
        Ok(StandardVolumeFlowUnit::StandardCubicFootPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "scfm").parse::<StandardVolumeFlow>(),
        Ok(StandardVolumeFlow::new(
            2.5,
            StandardVolumeFlowUnit::StandardCubicFootPerMinute
        ))
    );
    assert_eq!(
        "scfh".parse::<StandardVolumeFlowUnit>(),
        Ok(StandardVolumeFlowUnit::StandardCubicFootPerHour)
    );
    assert_eq!(
        format!("2.5 {}", "scfh").parse::<StandardVolumeFlow>(),
        Ok(StandardVolumeFlow::new(
            2.5,
            StandardVolumeFlowUnit::StandardCubicFootPerHour
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<StandardVolumeFlow>(),
        Err(ParseError::UnknownUnit)
    );
}

